xql_query:
// ============================================================
// Rule: O365_Public or External Sharing Link Created
// Vendor: Microsoft 365
// Objective:
// Detect activity associated with O365_Public or External Sharing Link Created.
// Severity: SEV_030_MEDIUM
// Category: EXFILTRATION
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.

dataset = msft_o365_sharepoint_online_raw
| filter operation = "AnonymousLinkCreated"
| filter USERID not in ("app@sharepoint", "<USER_EMAIL_1>")
| filter EventData contains "<Type>Edit</Type>" and EventData contains "<MembersCanShareApplied>True</MembersCanShareApplied>"
| fields _time, USERID, operation, SiteUrl, ObjectId, EventData
